using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.SGR.PerfilMenus;using GraphApi.Services.SGR.PerfilMenus;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.SGR.PerfilMenus{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de PerfilMenus: creación, actualización y eliminación.")]    public class PerfilMenusMutation    {        [Authorize]        [GraphQLName("createPerfilMenus")]        [GraphQLDescription("Crea un nuevo PerfilMenu usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadPerfilMenus> CreatePerfilMenusAsync(            [GraphQLDescription("Datos necesarios para crear el PerfilMenu.")]            clCreatePerfilMenus objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de PerfilMenu.")]            IPerfilMenusService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreatePerfilMenus(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updatePerfilMenus")]        [GraphQLDescription("Actualiza los campos especificados de un PerfilMenu existente.")]        public async Task<clReadPerfilMenus?> UpdatePerfilMenusAsync(            [GraphQLDescription("Datos del PerfilMenu a actualizar.")]            clUpdatePerfilMenus objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de PerfilMenu.")]            IPerfilMenusService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdatePerfilMenus(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deletePerfilMenus")]        [GraphQLDescription("Elimina un PerfilMenu por su ID.")]        public async Task<bool> delPerfilMenusAsync(            [GraphQLDescription("ID del PerfilMenu a eliminar.")]            int nPerfilMenusID,            [Service]            [GraphQLDescription("Servicio para operaciones de PerfilMenu.")]            IPerfilMenusService objService        )        {            return await objService.DeletePerfilMenus(nPerfilMenusID);        }    }}